export function dockerHost(value = process.env.GEBAL_DOCKER_HOST ?? 'unix:///var/run/docker.sock') {
  if (!/^unix:\/\/\/[^\x00-\x20,?#]+$/.test(value) || value.slice(7).split('/').includes('..'))
