export function processBounded(
  command: string,
  args: string[],
  seconds: number,
  maxBytes: number,
  signal?: AbortSignal,
): Promise<ProcessResult> {
  return new Promise((resolve) => {
    let stdout = '',
      stderr = '',
      bytes = 0,
      timedOut = false,
      overflow = false,
      cancelled = false,
      done = false;
    const child = spawn(command, command === 'docker' ? ['--host', dockerHost(), ...args] : args, {
      env: {
        PATH: '/opt/homebrew/bin:/usr/local/bin:/usr/bin:/bin',
        HOME: process.env.HOME || '',
        DOCKER_CONFIG: process.env.DOCKER_CONFIG || join(process.env.HOME || '', '.docker'),
      },
      stdio: ['ignore', 'pipe', 'pipe'],
      shell: false,
    });
    const stop = () => {
      cancelled = true;
      child.kill('SIGKILL');
    };
    const timer = setTimeout(() => {
      timedOut = true;
      child.kill('SIGKILL');
    }, seconds * 1000);
    const complete = (code: number | null) => {
      if (done) return;
      done = true;
      clearTimeout(timer);
      signal?.removeEventListener('abort', stop);
      resolve({ code, stdout, stderr, timedOut, cancelled, overflow });
    };
    for (const [stream, key] of [
      [child.stdout, 'stdout'],
      [child.stderr, 'stderr'],
    ] as const)
      stream.on('data', (data: Buffer) => {
        bytes += data.length;
        if (bytes > maxBytes) {
          overflow = true;
          child.kill('SIGKILL');
          return;
        }
        if (key === 'stdout') stdout += data.toString();
        else stderr += data.toString();
      });
    child.on('error', (e) => {
      stderr = e.message;
      complete(null);
    });
    child.on('close', complete);
    signal?.addEventListener('abort', stop, { once: true });
    if (signal?.aborted) stop();
  });
}
